    s[strcspn(s, "\n")] = 0;
    int n = (int)strlen(s);
    int end = n;
    int first = 1;
    for (int i = n - 1; i >= -1; i--) {
        if (i == -1 || s[i] == ' ') {
            int start = i + 1;
            if (start < end) {
                if (!first) putchar(' ');
                char *p = s + start;
                for (int k = 0; k < end - start; k++) putchar(p[k]);
                first = 0;
            }
            end = i;
        }
    }
    putchar('\n');
    return 0;
}

#include <stdio.h>
