int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    static char words[100][101];
    static int sig[100][26];
    int used[100];
    for (int i = 0; i < 100; i++) used[i] = 0;
    for (int i = 0; i < n; i++) {
        if (scanf("%100s", words[i]) != 1) return 0;
        for (int k = 0; k < 26; k++) sig[i][k] = 0;
        for (int k = 0; words[i][k]; k++) sig[i][words[i][k] - 'a']++;
    }
    int groups = 0;
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        groups++;
        used[i] = 1;
        for (int j = i + 1; j < n; j++) {
            if (used[j]) continue;
            int same = 1;
            for (int k = 0; k < 26; k++) {
                if (sig[i][k] != sig[j][k]) { same = 0; break; }
            }
            if (same) used[j] = 1;
        }
    }
    printf("%d\n", groups);
    return 0;
}

