#include <stdio.h>
#include <string.h>

int main(void) {
    char s[2048];
    if (fgets(s, sizeof(s), stdin) == NULL) return 0;
    s[strcspn(s, "\n")] = 0;
    int n = (int)strlen(s);
    char out[2048];
    char *src = s;
    char *dst = out;
    int out_idx = 0;
    int i = 0;
    int in_word = 0;
    int new_word = 1;
    while (i < n) {
        char c = src[i];
        if (c == ' ' || c == '\t') {
            in_word = 0;
        } else {
            if (!in_word) {
                if (out_idx > 0) dst[out_idx++] = ' ';
                in_word = 1;
                new_word = 1;
            }
            if (c >= 'a' && c <= 'z' && new_word) {
                dst[out_idx++] = (char)(c - 'a' + 'A');
            } else if (c >= 'A' && c <= 'Z' && !new_word) {
                dst[out_idx++] = (char)(c - 'A' + 'a');
            } else {
                dst[out_idx++] = c;
            }
            new_word = 0;
        }
        i++;
    }
    dst[out_idx] = 0;
    printf("%s\n", out);
    return 0;
}
